const n = (count: string, one: string, many: string) => `${count} ${count === '1' ? one : many}`;

/** Phrases with a number or a name in them. */
export const DA_PATTERNS: Language['patterns'] = [
  [/^Importing (.+)$/, (m) => `Importerer ${m[1]}`],
  [/^Linking (.+)$/, (m) => `Linker ${m[1]}`],
  [/^Reading (.+\.ifc)$/i, (m) => `Læser ${m[1]}`],
  [/^(.+) — ([^·]+?)(?: · (.+))?$/, (m) => `${DA[m[1]] ?? m[1]} — ${m[2]}${m[3] ? ` · ${DA[m[3]] ?? m[3]}` : ''}`],
  [/^(Fold|Unfold) the (project browser|properties)(?: \((.+)\))?$/, (m) => `${m[1] === 'Fold' ? 'Fold' : 'Udfold'} ${m[2] === 'properties' ? 'egenskaberne' : 'projektbrowseren'}${m[1] === 'Fold' ? ' ind' : ''}${m[3] ? ` (${m[3]})` : ''}`],
  [/^Keep the (project browser|properties) open(?: \((.+)\))?$/, (m) => `Hold ${m[1] === 'properties' ? 'egenskaberne' : 'projektbrowseren'} åben${m[2] ? ` (${m[2]})` : ''}`],
  [/^Quick tool (\d)$/, (m) => `Hurtigværktøj ${m[1]}`],
  [/^Object snap \((.+)\)$/, (m) => `Objektfang (${m[1]})`],
  [/^Ortho \((.+); hold Shift\)$/, (m) => `Ortho (${m[1]}; hold Shift nede)`],
  [/^Polar tracking every 45° \((.+)\)$/, (m) => `Polær sporing for hver 45° (${m[1]})`],
  [/^Reassign to (.+)$/, (m) => `Flyt til ${DA[m[1]] ?? m[1]}`],
  [/^Also used by (.+)$/, (m) => `Bruges også af ${m[1]}`],
  [/^In (.+)'s session, to look$/, (m) => `I ${m[1]}s session, som seer`],
  [/^In (.+)'s session$/, (m) => `I ${m[1]}s session`],
  [/^(.+) is in this plan\.$/, (m) => `${m[1]} er i denne plan.`],
  [/^(.+) is in 3D\.$/, (m) => `${m[1]} er i 3D.`],
  [/^Undo „(.+)”: (.+) changed it after you; it is left as it is\.$/, (m) => `Fortryd »${m[1]}«: ${m[2] === 'Someone' ? 'en anden' : m[2]} ændrede det efter dig; det bliver, som det er.`],
  [/^Redo „(.+)”: (.+) changed it after you; it is left as it is\.$/, (m) => `Annuller fortryd »${m[1]}«: ${m[2] === 'Someone' ? 'en anden' : m[2]} ændrede det efter dig; det bliver, som det er.`],
  [/^Segment (\d+) \((m|°|ratio)\)$/, (m) => `Segment ${m[1]} (${m[2] === 'ratio' ? 'forhold' : m[2]})`],
  [/^(aligned|linear) · (\d+) segments$/, (m) => `${m[1] === 'aligned' ? 'justeret' : 'lineær'} · ${m[2]} segmenter`],
  [/^(\d+) elements?$/, (m) => n(m[1], 'element', 'elementer')],
  [/^(\d+) of (\d+) storeys$/, (m) => `${m[1]} af ${m[2]} etager`],
  [/^cut at (.+) m$/, (m) => `skåret ved ${m[1]} m`],
  [/^Underlay: (.+)$/, (m) => `Underlag: ${m[1]}`],
  [/^(\d+) (survey points|feature\(s\)|building\(s\)) imported, in the project's coordinates \(Manage → Location shows its system and survey point\)\.$/, (m) => `${m[1]} ${({ 'survey points': 'opmålingspunkter', 'feature(s)': 'objekt(er)', 'building(s)': 'bygning(er)' } as Record<string, string>)[m[2]]} importeret, i projektets koordinater (Administrer → Placering viser dets system og opmålingspunkt).`],
  [/^(\d+) to check$/, (m) => `${m[1]} til kontrol`],
  [/^Plan · (.+)$/, (m) => `Plan · ${m[1]}`],
  [/^(\d+) line edit\(s\) lost their edge · clean$/, (m) => `${m[1]} linjeredigering(er) mistede deres kant · ryd op`],
  [/^view range: (\d+) problem\(s\)$/, (m) => `visningsområde: ${m[1]} problem(er)`],
  [/^(.+) · (\d+) selected$/, (m) => `${m[1]} · ${m[2]} valgt`],
  [/^Camera at (.+) m: drag$/, (m) => `Kamera i ${m[1]} m: træk`],
  [/^(Key plan|On screen|Seen from|Cut at) · (.+)$/, (m) => `${({ 'Key plan': 'Oversigtsplan', 'On screen': 'På skærmen', 'Seen from': 'Set fra', 'Cut at': 'Snit ved' } as Record<string, string>)[m[1]]} · ${m[2]}`],
  [/^Terrain created from (\d+) points\.$/, (m) => `Terræn oprettet ud fra ${m[1]} punkter.`],
  [/^(\d+) element\(s\) moved to (.+)\.$/, (m) => `${m[1]} element(er) flyttet til ${m[2]}.`],
  [/^(\d+) element\(s\) selected, now on (.+)\.$/, (m) => `${m[1]} element(er) valgt, nu på ${m[2]}.`],
  [/^Type parameters · (.+)$/, (m) => `Typeparametre · ${m[1]}`],
  [/^(\d+) bays along × (\d+) up · IFC: (.+)$/, (m) => `${m[1]} fag langs × ${m[2]} op · IFC: ${m[3]}`],
  [/^(\d+) value\(s\) added\.$/, (m) => `${m[1]} værdi(er) tilføjet.`],
  [/^(\d+) room\(s\) updated\.$/, (m) => `${m[1]} rum opdateret.`],
  [/^IFC properties · (\d+)$/, (m) => `IFC-egenskaber · ${m[1]}`],
  [/^(.+) could not be read as a picture: attach a PNG or JPEG screenshot \(or send the report without one\)\.$/, (m) => `${m[1]} kunne ikke læses som et billede: vedhæft et PNG- eller JPEG-skærmbillede (eller send rapporten uden).`],
  [/^(\d+) room\(s\) updated; (\d+) no longer enclosed \(they keep their last outline\)\.$/, (m) => `${m[1]} rum opdateret; ${m[2]} ikke længere lukket (de beholder deres seneste omrids).`],
  [/^No room has a value for this field yet\. Give rooms a (.+) in their properties\.$/, (m) => `Intet rum har endnu en værdi i dette felt. Giv rummene en værdi (${DA[m[1]] ?? m[1]}) i deres egenskaber.`],
  // The model assistant's lines: its steps, its tables, what it applied
  [/^Listed (\d+) of (\d+) · (.+)$/, (m) => `Listede ${m[1]} af ${m[2]} · ${m[3] === 'all' ? 'alle' : m[3]}`],
  [/^Computed (\d+) group\(s\) over (\d+) element\(s\)$/, (m) => `Beregnede ${m[1]} gruppe(r) over ${m[2]} element(er)`],
  [/^Read element (.+)$/, (m) => `Læste elementet ${m[1]}`],
  [/^Read schedule (.+)$/, (m) => `Læste skemaet ${m[1]}`],
  [/^Proposed (\d+) change\(s\)$/, (m) => `Foreslog ${m[1]} ændring(er)`],
  [/^Proposed (\d+) change\(s\), (\d+) refused$/, (m) => `Foreslog ${m[1]} ændring(er), ${m[2]} afvist`],
  [/^Tool failed: (.+)$/, (m) => `Værktøjet fejlede: ${m[1]}`],
  [/^(\d+) row\(s\)$/, (m) => `${m[1]} række(r)`],
  [/^(\d+) value\(s\) applied: one step to undo\.$/, (m) => `${m[1]} værdi(er) anvendt: ét trin at fortryde.`],
  [/^Grouped by (.+)$/, (m) => `Grupperet efter ${m[1]}`],
  [/^(\d+) of (\d+) ticked$/, (m) => `${m[1]} af ${m[2]} afkrydset`],
  // The undo buttons' tooltips: "Undo Move (Ctrl+Z)", "Redo (Ctrl+Y, Ctrl+Shift+Z)"
  [/^(Undo|Redo) \(([^()]+)\)$/, (m) => `${m[1] === 'Undo' ? 'Fortryd' : 'Annuller fortryd'} (${m[2]})`],
  [/^(Undo|Redo) (.+?)(?: \(([^()]+)\))?$/, (m) => `${m[1] === 'Undo' ? 'Fortryd' : 'Annuller fortryd'} ${DA[m[2]] ?? m[2]}${m[3] ? ` (${m[3]})` : ''}`],
];
